BEGIN;
CREATE TEMP TABLE credit_test_context AS SELECT (SELECT count(*) FROM public.enterprise_finance_accounts) accounts,(SELECT count(*) FROM public.finance_credit_cards) cards;
SELECT set_config('request.jwt.claim.sub','b2f6e43d-ce24-4de2-a770-0548793cc180',true);
SET LOCAL ROLE authenticated;
DO $$DECLARE card uuid; bank uuid; center uuid; purchase uuid; p public.finance_card_purchases; payload jsonb; total bigint; parts integer; invoice date;BEGIN
 INSERT INTO public.finance_bank_accounts(name,opening_balance_cents,opening_on) VALUES('Cartão banco teste rollback',100000,current_date) RETURNING id INTO bank;
 INSERT INTO public.finance_cost_centers(name,kind) VALUES('Cartão centro teste rollback','expense') RETURNING id INTO center;
 INSERT INTO public.finance_credit_cards(name,bank_label,closing_day,due_day,bank_account_id) VALUES('Cartão teste rollback','Itaú',25,5,bank) RETURNING id INTO card;
 payload:=jsonb_build_object('card_id',card,'description','Compra teste','amount_cents',10001,'purchased_on',current_date,'installments',3,'cost_center_id',center);
 purchase:=public.save_card_purchase(payload);
 SELECT * INTO p FROM public.finance_card_purchases WHERE id=purchase;
 SELECT count(*),sum(amount_cents),min(invoice_month) INTO parts,total,invoice FROM public.enterprise_finance_accounts WHERE card_purchase_id=purchase AND deleted_at IS NULL;
 IF parts<>3 OR total<>10001 THEN RAISE EXCEPTION 'Installment allocation failed';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.enterprise_finance_accounts WHERE card_purchase_id=purchase AND installment_number=1 AND amount_cents=3334 AND cost_center_id=center AND bank_account_id=bank) THEN RAISE EXCEPTION 'First installment/metadata failed';END IF;
 BEGIN UPDATE public.enterprise_finance_accounts SET amount_cents=1 WHERE card_purchase_id=purchase;RAISE EXCEPTION 'Direct modification accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM='Direct modification accepted' THEN RAISE;END IF;END;
 PERFORM public.settle_card_invoice(card,invoice,current_date,bank,3334);
 IF (SELECT sum(amount_cents) FROM public.enterprise_finance_accounts WHERE card_purchase_id=purchase AND settled_on IS NOT NULL)<>3334 THEN RAISE EXCEPTION 'Statement settlement mismatch';END IF;
 BEGIN PERFORM public.save_card_purchase(payload,purchase,p.updated_at);RAISE EXCEPTION 'Paid purchase edited';EXCEPTION WHEN raise_exception THEN IF SQLERRM='Paid purchase edited' THEN RAISE;END IF;END;
 BEGIN PERFORM public.settle_card_invoice(card,invoice,NULL,NULL,9999);RAISE EXCEPTION 'Stale total accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM='Stale total accepted' THEN RAISE;END IF;END;
 PERFORM public.settle_card_invoice(card,invoice,NULL,NULL,3334);
 PERFORM public.save_card_purchase(payload||jsonb_build_object('amount_cents',12000,'installments',2),purchase,p.updated_at);
 IF (SELECT sum(amount_cents) FROM public.enterprise_finance_accounts WHERE card_purchase_id=purchase AND deleted_at IS NULL)<>12000 OR (SELECT count(*) FROM public.enterprise_finance_accounts WHERE card_purchase_id=purchase AND deleted_at IS NULL)<>2 THEN RAISE EXCEPTION 'Edit duplicated installments';END IF;
 SELECT * INTO p FROM public.finance_card_purchases WHERE id=purchase;
 PERFORM public.set_card_purchase_deleted(purchase,p.updated_at,true);
 IF EXISTS(SELECT 1 FROM public.enterprise_finance_accounts WHERE card_purchase_id=purchase AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Deleted purchase still payable';END IF;
 SELECT * INTO p FROM public.finance_card_purchases WHERE id=purchase;
 PERFORM public.set_card_purchase_deleted(purchase,p.updated_at,false);
 IF (SELECT count(*) FROM public.enterprise_finance_accounts WHERE card_purchase_id=purchase AND deleted_at IS NULL)<>2 THEN RAISE EXCEPTION 'Restore revived removed installments';END IF;
 IF public.finance_card_date('2028-02-01',31)<>'2028-02-29'::date THEN RAISE EXCEPTION 'Leap month date failed';END IF;
END $$;
SELECT set_config('request.jwt.claim.sub','a6fd10de-33d6-45c3-b423-9290dad107ea',true);
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM public.finance_credit_cards) OR EXISTS(SELECT 1 FROM public.finance_card_purchases) THEN RAISE EXCEPTION 'Collaborator reads credit cards';END IF;
 BEGIN PERFORM public.save_card_purchase('{}');RAISE EXCEPTION 'Collaborator writes card purchase';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO public.finance_credit_cards(name,closing_day,due_day) VALUES('Inválido',1,10);RAISE EXCEPTION 'Collaborator creates card';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: cartão, parcelas, centavos, baixa única, edição/exclusão/restauração, fechamento e RLS; sem dados fictícios persistidos' result;
